INSERT INTO "blog_blocks" ("post_id", "position", "type", "data") VALUES
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 0, $s$itinerary_with_map$s$, $s${"itineraryId":"fb6d7286-acab-4b5a-9b6a-2c7127870958"}$s$::jsonb),
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 1, $s$two_column$s$, $s${"leftType":"image","rightType":"text","leftImage":"aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1723","html":"Our first stop was 📌Arima, a town steeped in history and brimming with local charm. We savored the vibrant atmosphere, soaking in the sights and sounds of the bustling market."}$s$::jsonb),
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 2, $s$text$s$, $s${"html":"As we continued west, the sky darkened, and clouds gathered on the horizon. Undeterred, we pressed on towards 📌Sangre Grande. Imagine our surprise when we encountered a bustling market in the center of a roundabout! Local vendors showcased their wares – fresh produce, colorful crafts, and mouthwatering local delicacies. We couldn't resist indulging in the quintessential Trinidadian treat: doubles."}$s$::jsonb),
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 3, $s$text$s$, $s${"html":"With the rain starting to fall, we made our way towards 📌Manzanilla Beach. The road conditions deteriorated rapidly, so we made a quick stop by the beach and then decided to head back to the hotel. Despite the unexpected weather, our journey through the heart of Trinidad was a captivating experience. We encountered the warmth of local communities, savored delicious treats, and witnessed the raw beauty of the island's interior."}$s$::jsonb),
  ($s$91acb62d-46a1-4fc0-97b7-f9fbe3b4a866$s$, 4, $s$image_grid$s$, $s${"images":["aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1731","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1737","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1728","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1724","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1721","aroundtheworld50s/blog/trinidad-and-tobago/3/IMG_1725"]}$s$::jsonb);
